const ROWS=[['FP_LEFT','FF','FP_RIGHT'],['HFF_LEFT','CHF','HFF_RIGHT'],['RUCK','RUCK_ROVER','ROVER'],['WING_LEFT','CENTRE','WING_RIGHT'],['HBF_LEFT','CHB','HBF_RIGHT'],['BP_LEFT','FB','BP_RIGHT']] as const
const BENCH=['INTERCHANGE_1','INTERCHANGE_2','INTERCHANGE_3','INTERCHANGE_4'] as const
const LABELS:Record<string,string>={BP_LEFT:'RBP',FB:'FB',BP_RIGHT:'LBP',HBF_LEFT:'RHB',CHB:'CHB',HBF_RIGHT:'LHB',WING_LEFT:'RW',CENTRE:'C',WING_RIGHT:'LW',RUCK:'R',RUCK_ROVER:'RR',ROVER:'ROV',HFF_LEFT:'RHF',CHF:'CHF',HFF_RIGHT:'LHF',FP_LEFT:'RFP',FF:'FF',FP_RIGHT:'LFP',INTERCHANGE_1:'INT 1',INTERCHANGE_2:'INT 2',INTERCHANGE_3:'INT 3',INTERCHANGE_4:'INT 4'}
const EMPTY_STATS:TeamStats={inside50s:0,clearances:0,tackles:0,marks:0,rebound50s:0,onePercenters:0,freesAgainst:0}
const DEFAULT_TARGETS:TeamStats={inside50s:12,clearances:10,tackles:16,marks:10,rebound50s:8,onePercenters:12,freesAgainst:5}
const KPIS:Array<{key:StatKey;label:string;short:string}>=[{key:'inside50s',label:'Inside 50s',short:'I50'},{key:'clearances',label:'Clearances',short:'CLR'},{key:'tackles',label:'Tackles',short:'TKL'},{key:'marks',label:'Marks',short:'MRK'},{key:'rebound50s',label:'Rebound 50s',short:'R50'},{key:'onePercenters',label:'One percenters',short:'1%'},{key:'freesAgainst',label:'Frees against',short:'FA'}]
const id=()=>`${Date.now()}-${Math.random().toString(36).slice(2)}`
const total=(goals:number,behinds:number)=>goals*6+behinds
const formatTime=(seconds:number)=>`${String(Math.floor(Math.max(0,seconds)/60)).padStart(2,'0')}:${String(Math.floor(Math.max(0,seconds))%60).padStart(2,'0')}`
const isOnGround=(code:string)=>FIELD.has(code)
const currentSeconds=(state:MatchState)=>state.elapsed+(state.runningSince?Math.floor((Date.now()-state.runningSince)/1000):0)
const normalise=(state:MatchState):MatchState=>({...state,teamStats:{...EMPTY_STATS,...(state.teamStats??{})},kpiTargets:{...DEFAULT_TARGETS,...(state.kpiTargets??{})},scoreUndo:Array.isArray(state.scoreUndo)?state.scoreUndo:[],totalTrackedSeconds:Number(state.totalTrackedSeconds)||0,trackingUpdatedAt:state.runningSince?(Number(state.trackingUpdatedAt)||Date.now()):null,slots:state.slots.map(slot=>{const onGround=isOnGround(slot.positionCode),onGroundSeconds=Number(slot.onGroundSeconds)||0;return {...slot,onGround,goals:Number(slot.goals)||0,behinds:Number(slot.behinds)||0,plusMinus:Number(slot.plusMinus)||0,onGroundSeconds,benchSeconds:Number(slot.benchSeconds)||0,benchEnteredAt:typeof slot.benchEnteredAt==='number'?slot.benchEnteredAt:null,fresh:typeof slot.fresh==='boolean'?slot.fresh:!onGround&&onGroundSeconds===0,injured:Boolean(slot.injured)}})})

